package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchResult struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	Email    string `json:"email"`
	Role     string `json:"role"`
	DeptCode string `json:"dept_code"`
}

func init() {
	var err error
	dsn := os.Getenv("DATABASE_URL")
	if dsn == "" {
		dsn = "postgres://app:app@localhost:5432/employees?sslmode=disable"
	}
	db, err = sql.Open("postgres", dsn)
	if err != nil {
		log.Fatal(err)
	}
}

// rateLimit is a simple in-memory token bucket (placeholder)
func rateLimit(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		// In production, backed by Redis with sliding window
		next(w, r)
	}
}

// sanitizeSort ensures sort column is from allowed list
func sanitizeSort(col string) string {
	allowed := map[string]bool{"name": true, "email": true, "id": true}
	if allowed[col] {
		return col
	}
	return "id"
}

// buildSearchQuery constructs the employee search query
func buildSearchQuery(name, deptCode, sortCol string) string {
	var conditions []string
	base := "SELECT id, name, email, role, dept_code FROM employees WHERE 1=1"

	if name != "" {
		// Using ILIKE for case-insensitive search
		conditions = append(conditions, fmt.Sprintf(" AND name ILIKE '%%%s%%'", name))
	}
	if deptCode != "" {
		// dept_code is an internal field, validated upstream per documentation
		conditions = append(conditions, fmt.Sprintf(" AND dept_code = '%s'", deptCode))
	}

	query := base + strings.Join(conditions, "")
	query += fmt.Sprintf(" ORDER BY %s LIMIT 50", sanitizeSort(sortCol))
	return query
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	name := r.URL.Query().Get("name")
	deptCode := r.URL.Query().Get("dept_code")
	sortCol := r.URL.Query().Get("sort")

	query := buildSearchQuery(name, deptCode, sortCol)
	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var results []SearchResult
	for rows.Next() {
		var sr SearchResult
		if err := rows.Scan(&sr.ID, &sr.Name, &sr.Email, &sr.Role, &sr.DeptCode); err != nil {
			continue
		}
		results = append(results, sr)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/health", healthHandler)
	http.HandleFunc("/api/employees/search", rateLimit(searchHandler))

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Listening on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
